--- To find the start and end ip from the ip/cidr
-- @function calculateIPRange
-- @param ip the ip address in the form of ip/cidr or start-endip or ip
-- @return ipmin the start address
-- @return ipmax the end address
local function calculateIPRange(ip)
  local ipmin = ip
  local ipmax = ip
  if ip:match("/") then
    local base, mask = ip:match("(.*)/(.*)")
    base = base and ipv4ToNum(base)
    mask = mask and ipv4ToNum(nwCommon.netmask2mask(tonumber(mask)))
    if base and mask then
      local network = bit.band(base, mask)
      ipmin = numToIPv4(network + 1)
      ipmax = numToIPv4(bit.bor(network, bit.bnot(mask)) - 1)
    end
  elseif ip:match("-") then
    ipmin, ipmax = ip:match("^(.*)-(.*)")
  end
  return ipmin, ipmax
end

