  end
}

InternetGatewayDevice_X_Management_AccessControl_List_i_.set = {
  SourceIPStart = function(mapping, param, value, key)
    local rc, err = isValidIP(value)
    if not rc then
      return nil, err
    end
    local ip = getFromUci(key, "ip")
    if ip ~= "" then
      local _, max = calculateIPRange(ip)
      value = value .. "-" .. max
    end
    setOnUci(key, "ip", value)
  end,
  SourceIPEnd = function(mapping, param, value, key)
    local rc, err = isValidIP(value)
    if not rc then
      return nil, err
    end
    if ip ~= "" then
      local ip = getFromUci(key, "ip")
      local min = calculateIPRange(ip)
      value = min .. "-" ..value
    end
    setOnUci(key, "ip", value)
  end,
}

